insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('riz pilaf', 'Riz pilaf', array['riz pilaw', 'pilaf', 'riz au four']::text[], 'dish', $r$[{"title":"Riz pilaf","intro":"Du riz nacré à l'oignon puis cuit dans un bouillon, aux grains bien détachés.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre l'oignon émincé dans le beurre.","timer":null},{"text":"Ajoute le riz et remue 2 min jusqu'à ce qu'il soit nacré.","timer":null},{"text":"Verse 60 cl de bouillon chaud et ajoute le thym.","timer":null},{"text":"Couvre et laisse cuire 17 min à feu doux sans remuer.","timer":{"label":"Cuisson","min":17}}],"kids":true,"variant":"La classique","change":""},{"title":"Riz pilaf aux légumes","intro":"Un riz pilaf coloré, complet avec ses légumes.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"vegetable rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":100,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'oignon, la carotte et le poivron en dés dans l'huile.","timer":null},{"text":"Ajoute le riz et remue 2 min.","timer":null},{"text":"Verse 60 cl de bouillon chaud et laisse cuire 12 min à couvert.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute les petits pois et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"kids":true,"variant":"Aux légumes","change":"Avec des carottes, des petits pois et du poivron."},{"title":"Riz pilaf aux épices","intro":"Un riz pilaf doré à l'orientale.","minutes":30,"calories":310,"difficulty":"Facile","imageSearch":"spiced rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration orientale","serves":4,"items":[{"name":"riz basmati","plural":"riz basmati","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"bâton de cannelle","plural":"bâtons de cannelle","qty":1,"unit":"","have":false},{"name":"raisins secs","plural":"raisins secs","qty":40,"unit":"g","have":false},{"name":"amandes effilées","plural":"amandes effilées","qty":30,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon avec le curcuma et la cannelle.","timer":null},{"text":"Ajoute le riz et remue 2 min.","timer":null},{"text":"Verse 55 cl de bouillon chaud, ajoute les raisins et laisse cuire 15 min à couvert.","timer":{"label":"Cuisson","min":15}},{"text":"Parsème d'amandes grillées.","timer":null}],"variant":"Aux épices","change":"Parfumé au curcuma, à la cannelle et aux raisins secs."}]$r$::jsonb, 'claude')
