insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('oeuf cocotte', 'Œufs cocotte', array['oeuf en cocotte']::text[], 'dish', $r$[{"title":"Œufs cocotte à la crème","intro":"Des œufs cuits au four dans des ramequins, avec de la crème et de la ciboulette.","minutes":20,"calories":200,"difficulty":"Facile","imageSearch":"baked eggs ramekin cream","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":8,"unit":"c. à s.","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":10,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Beurre 4 ramequins.","timer":null},{"text":"Mets 1 c. à s. de crème au fond, casse un œuf, puis encore 1 c. à s. de crème.","timer":null},{"text":"Pose les ramequins dans un plat avec de l'eau chaude à mi-hauteur.","timer":null},{"text":"Enfourne 10 min : le blanc doit être pris et le jaune coulant.","timer":{"label":"Four","min":10}},{"text":"Parsème de ciboulette, sale et poivre.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Œufs cocotte au jambon","intro":"Des œufs cocotte gourmands au jambon et à l'emmental.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"baked eggs ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":2,"unit":"tranches","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"c. à s.","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":40,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mets le jambon en dés et la crème dans 4 ramequins beurrés.","timer":null},{"text":"Casse un œuf dans chacun et parsème d'emmental.","timer":null},{"text":"Enfourne 12 min au bain-marie.","timer":{"label":"Four","min":12}}],"kids":true,"variant":"Au jambon","change":"Avec du jambon et du fromage."},{"title":"Œufs cocotte aux champignons","intro":"Des œufs cocotte forestiers, aux champignons.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"baked eggs mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"c. à s.","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais revenir les champignons émincés et l'échalote 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Répartis-les dans 4 ramequins avec la crème et casse un œuf dans chacun.","timer":null},{"text":"Enfourne 12 min au bain-marie et parsème de persil.","timer":{"label":"Four","min":12}}],"kids":true,"variant":"Aux champignons","change":"Avec une poêlée de champignons."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pain maison', 'Pain maison', array['pain', 'faire son pain', 'pain fait maison', 'pain san machine']::text[], 'dish', $r$[{"title":"Pain maison","intro":"Un pain croustillant fait à la main, sans machine, cuit dans une cocotte.","minutes":210,"calories":250,"difficulty":"Moyen","imageSearch":"homemade bread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":500,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":5,"unit":"g","have":false},{"name":"sel","plural":"sel","qty":10,"unit":"g","have":false}],"steps":[{"text":"Délaye la levure dans 35 cl d'eau tiède.","timer":null},{"text":"Mélange avec la farine et le sel, et pétris 10 min.","timer":{"label":"Pétrissage","min":10}},{"text":"Laisse lever 2 h sous un torchon.","timer":{"label":"Levée","min":120}},{"text":"Préchauffe le four à 240 °C avec une cocotte en fonte dedans.","timer":null},{"text":"Façonne une boule, mets-la dans la cocotte chaude et enfourne 30 min à couvert, puis 15 min sans couvercle.","timer":{"label":"Four","min":45}}],"variant":"La classique","change":""},{"title":"Pain sans pétrissage","intro":"Le pain le plus simple, qui se prépare la veille.","minutes":60,"calories":250,"difficulty":"Facile","imageSearch":"no knead bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":500,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":2,"unit":"g","have":false},{"name":"sel","plural":"sel","qty":10,"unit":"g","have":false}],"steps":[{"text":"Mélange la farine, le sel, la levure et 38 cl d'eau tiède, sans pétrir.","timer":null},{"text":"Couvre et laisse lever 12 à 18 h à température ambiante.","timer":null},{"text":"Préchauffe le four à 240 °C avec une cocotte en fonte dedans.","timer":null},{"text":"Verse la pâte dans la cocotte chaude et enfourne 30 min à couvert, puis 15 min sans couvercle.","timer":{"label":"Four","min":45}}],"variant":"Sans pétrir","change":"La pâte lève toute une nuit et ne se pétrit pas."},{"title":"Pain complet aux graines","intro":"Un pain complet riche en graines, pour le petit-déjeuner.","minutes":210,"calories":270,"difficulty":"Moyen","imageSearch":"whole wheat seeded bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine complète","plural":"farine complète","qty":300,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":5,"unit":"g","have":false},{"name":"graines mélangées","plural":"graines mélangées","qty":80,"unit":"g","have":false},{"name":"sel","plural":"sel","qty":10,"unit":"g","have":false}],"steps":[{"text":"Délaye la levure dans 37 cl d'eau tiède.","timer":null},{"text":"Mélange avec les farines, le sel et les graines, et pétris 10 min.","timer":{"label":"Pétrissage","min":10}},{"text":"Laisse lever 2 h.","timer":{"label":"Levée","min":120}},{"text":"Façonne et mets dans un moule à cake. Laisse lever 45 min.","timer":{"label":"Levée","min":45}},{"text":"Enfourne 40 min à 220 °C.","timer":{"label":"Four","min":40}}],"variant":"Complet","change":"Avec de la farine complète et des graines."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('frittata', 'Frittata', array['omelette italienne', 'tortilla espagnole', 'tortilla de patata']::text[], 'dish', $r$[{"title":"Frittata aux légumes","intro":"L'omelette épaisse à l'italienne, garnie de légumes et finie au four.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"vegetable frittata","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":8,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais revenir l'oignon, le poivron et la courgette en dés 8 min dans une poêle qui va au four.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec le parmesan, sale et poivre, et verse sur les légumes.","timer":null},{"text":"Laisse cuire 3 min sur le feu, puis enfourne 12 min.","timer":{"label":"Four","min":12}}],"kids":true,"variant":"La classique","change":""},{"title":"Tortilla espagnole","intro":"L'omelette espagnole épaisse aux pommes de terre.","minutes":45,"calories":350,"difficulty":"Moyen","imageSearch":"spanish tortilla","veg":true,"oven":false,"cold":false,"missing":"","origin":"Recette espagnole","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":10,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les pommes de terre en fines lamelles et l'oignon en lamelles.","timer":null},{"text":"Fais-les cuire 20 min à feu doux dans l'huile, sans les dorer.","timer":{"label":"Poêle","min":20}},{"text":"Égoutte-les et mélange-les aux œufs battus salés.","timer":null},{"text":"Remets dans la poêle et cuis 5 min, puis retourne avec une assiette et cuis 3 min.","timer":{"label":"Poêle","min":8}}],"kids":true,"variant":"Tortilla","change":"Avec des pommes de terre et de l'oignon."},{"title":"Frittata épinards et feta","intro":"Une frittata verte et fondante.","minutes":25,"calories":290,"difficulty":"Facile","imageSearch":"spinach feta frittata","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":8,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":200,"unit":"g","have":false},{"name":"feta","plural":"fetas","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre les épinards avec l'oignon 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Verse les œufs battus et la feta émiettée.","timer":null},{"text":"Laisse cuire 3 min puis enfourne 12 min.","timer":{"label":"Four","min":12}}],"variant":"Épinards et feta","change":"Avec des épinards et de la feta."}]$r$::jsonb, 'claude')
