insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('croque madame', 'Croque-madame', array[]::text[], 'dish', $r$[{"title":"Croque-madame","intro":"Le croque-monsieur coiffé d'un œuf au plat.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"croque madame","veg":false,"oven":true,"cold":false,"missing":"","origin":"Bistrot français","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Beurre le pain, garnis de jambon et d'emmental et referme.","timer":null},{"text":"Couvre de crème et du reste d'emmental, et enfourne 12 min.","timer":{"label":"Four","min":12}},{"text":"Fais cuire les œufs au plat.","timer":{"label":"Poêle","min":4}},{"text":"Pose un œuf sur chaque croque.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Croque-madame à la béchamel","intro":"Le croque-madame du bistrot, crémeux à la béchamel.","minutes":35,"calories":580,"difficulty":"Moyen","imageSearch":"croque madame bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":25,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":20,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false}],"steps":[{"text":"Prépare une béchamel avec 20 g de beurre, la farine et le lait.","timer":null},{"text":"Garnis le pain de jambon et d'emmental, referme et nappe de béchamel.","timer":null},{"text":"Parsème d'emmental et enfourne 12 min à 200 °C.","timer":{"label":"Four","min":12}},{"text":"Fais cuire les œufs au plat et pose-les dessus.","timer":null}],"variant":"Béchamel","change":"Nappé de béchamel avant de gratiner."},{"title":"Croque-madame végétarien","intro":"Un croque-madame sans viande, tomate et épinards.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"vegetarian croque madame","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":80,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Garnis le pain beurré de tomates en rondelles, d'épinards et d'emmental, et referme.","timer":null},{"text":"Parsème d'emmental et enfourne 12 min.","timer":{"label":"Four","min":12}},{"text":"Pose un œuf au plat sur chaque croque.","timer":null}],"kids":true,"variant":"Végétarien","change":"Avec des tomates et des épinards à la place du jambon."}]$r$::jsonb, 'claude')
