insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('bibimbap', 'Bibimbap', array['bibimbap coreen', 'riz coreen']::text[], 'dish', $r$[{"title":"Bibimbap","intro":"Le bol coréen : riz, bœuf mariné, légumes sautés, œuf au plat et sauce pimentée.","minutes":45,"calories":580,"difficulty":"Moyen","imageSearch":"bibimbap","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette coréenne","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"pâte de piment coréenne","plural":"pâte de piment coréenne","qty":2,"unit":"c. à s.","have":false},{"name":"huile de sésame","plural":"huile de sésame","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir le bœuf avec 2 c. à s. de sauce soja et 1 c. à s. d'huile de sésame.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter séparément les carottes et la courgette en bâtonnets, puis les épinards.","timer":{"label":"Poêle","min":8}},{"text":"Fais cuire les œufs au plat.","timer":{"label":"Poêle","min":4}},{"text":"Mets le riz dans des bols, dispose les légumes et le bœuf en parts, pose l'œuf.","timer":null},{"text":"Sers avec la pâte de piment mélangée au reste de sauce soja.","timer":null}],"variant":"La classique","change":""},{"title":"Bibimbap au tofu","intro":"Le bibimbap végétarien, au tofu croustillant.","minutes":40,"calories":500,"difficulty":"Moyen","imageSearch":"tofu bibimbap","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"tofu ferme","plural":"tofu ferme","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"pâte de piment coréenne","plural":"pâte de piment coréenne","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le tofu en dés avec 2 c. à s. de sauce soja.","timer":{"label":"Poêle","min":8}},{"text":"Fais sauter les carottes, la courgette et les épinards.","timer":{"label":"Poêle","min":8}},{"text":"Monte les bols avec le riz, les légumes, le tofu et un œuf au plat.","timer":null},{"text":"Sers avec la sauce pimentée.","timer":null}],"variant":"Végétarien","change":"Du tofu doré à la place du bœuf."},{"title":"Bibimbap au poulet","intro":"Un bibimbap plus doux, au poulet.","minutes":45,"calories":540,"difficulty":"Moyen","imageSearch":"chicken bibimbap bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"miel","plural":"miels","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le poulet en lamelles avec la sauce soja et le miel.","timer":{"label":"Poêle","min":8}},{"text":"Fais sauter les carottes et les épinards, et coupe le concombre en bâtonnets.","timer":null},{"text":"Monte les bols et ajoute un œuf au plat.","timer":null}],"variant":"Au poulet","change":"Avec du poulet mariné au soja."}]$r$::jsonb, 'claude')
