insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('maki', 'Makis', array['sushi', 'sushi maison', 'california roll', 'california']::text[], 'dish', $r$[{"title":"Makis au saumon","intro":"Des rouleaux de riz vinaigré et d'algue nori, au saumon et au concombre.","minutes":70,"calories":350,"difficulty":"Difficile","imageSearch":"salmon maki sushi","veg":false,"oven":false,"cold":true,"missing":"","origin":"Recette japonaise","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":300,"unit":"g","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":5,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false},{"name":"feuilles de nori","plural":"feuilles de nori","qty":5,"unit":"","have":false},{"name":"saumon frais","plural":"saumon frais","qty":250,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Rince le riz jusqu'à ce que l'eau soit claire, puis fais-le cuire 12 min avec 36 cl d'eau, à couvert.","timer":{"label":"Cuisson","min":12}},{"text":"Laisse reposer 10 min, puis mélange avec le vinaigre, le sucre et une pincée de sel. Laisse refroidir.","timer":null},{"text":"Coupe le saumon et le concombre en bâtonnets.","timer":null},{"text":"Étale une fine couche de riz sur une feuille de nori, pose saumon et concombre au bord.","timer":null},{"text":"Roule serré avec une natte, puis coupe en 6 avec un couteau mouillé.","timer":null},{"text":"Sers avec la sauce soja.","timer":null}],"variant":"La classique","change":""},{"title":"California rolls","intro":"Les rouleaux inversés à l'avocat et au surimi, roulés dans le sésame.","minutes":70,"calories":380,"difficulty":"Difficile","imageSearch":"california roll","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":300,"unit":"g","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":5,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false},{"name":"feuilles de nori","plural":"feuilles de nori","qty":4,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"surimi","plural":"surimi","qty":8,"unit":"","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare le riz vinaigré et laisse-le refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Étale le riz sur une feuille de nori, parsème de sésame et retourne-la sur un film.","timer":null},{"text":"Pose avocat et surimi en bâtonnets sur la nori.","timer":null},{"text":"Roule serré et coupe en 8.","timer":null}],"variant":"California","change":"Le riz à l'extérieur, avec avocat et surimi."},{"title":"Makis végétariens","intro":"Des makis tout légumes, frais et colorés.","minutes":60,"calories":280,"difficulty":"Difficile","imageSearch":"vegetable maki","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":300,"unit":"g","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":5,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false},{"name":"feuilles de nori","plural":"feuilles de nori","qty":5,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false}],"steps":[{"text":"Prépare le riz vinaigré et laisse-le refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe l'avocat, le concombre et la carotte en bâtonnets.","timer":null},{"text":"Étale le riz sur la nori, pose les légumes au bord et roule serré.","timer":null},{"text":"Coupe en 6 et sers avec de la sauce soja.","timer":null}],"variant":"Végétariens","change":"Avec avocat, concombre et carotte."}]$r$::jsonb, 'claude')
