insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('soupe au pistou', 'Soupe au pistou', array['pistou', 'soupe pistou']::text[], 'dish', $r$[{"title":"Soupe au pistou","intro":"La soupe provençale de légumes d'été et de haricots, avec son pistou au basilic.","minutes":60,"calories":380,"difficulty":"Facile","imageSearch":"soupe au pistou","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spécialité provençale","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":200,"unit":"g","have":false},{"name":"haricots blancs","plural":"haricots blancs","qty":400,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"petites pâtes","plural":"petites pâtes","qty":80,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":6,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe tous les légumes en petits dés.","timer":null},{"text":"Mets-les dans 2 litres d'eau salée et laisse cuire 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les haricots blancs égouttés et les pâtes, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Pile le basilic, l'ail, le parmesan et l'huile d'olive : c'est le pistou.","timer":null},{"text":"Ajoute le pistou hors du feu, au moment de servir.","timer":null}],"variant":"La classique","change":""},{"title":"Soupe au pistou express","intro":"La soupe au pistou en 25 minutes.","minutes":25,"calories":350,"difficulty":"Facile","imageSearch":"quick vegetable bean soup pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"légumes pour soupe surgelés","plural":"légumes pour soupe surgelés","qty":600,"unit":"g","have":false},{"name":"haricots blancs","plural":"haricots blancs","qty":400,"unit":"g","have":false},{"name":"petites pâtes","plural":"petites pâtes","qty":80,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"c. à s.","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false}],"steps":[{"text":"Porte 1,5 litre d'eau à ébullition avec le bouillon.","timer":null},{"text":"Ajoute les légumes et laisse cuire 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute les haricots et les pâtes, et laisse 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute le pesto hors du feu.","timer":null}],"variant":"Express","change":"Avec des légumes surgelés et un pesto tout prêt."},{"title":"Minestrone au pistou","intro":"Une soupe printanière toute verte, au pistou.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"green minestrone pistou","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":150,"unit":"g","have":false},{"name":"fèves surgelées","plural":"fèves surgelées","qty":150,"unit":"g","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir le poireau émincé dans un peu d'huile.","timer":null},{"text":"Ajoute les courgettes en dés et 1,5 litre d'eau salée, et laisse cuire 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute les petits pois et les fèves 8 min, puis les épinards.","timer":{"label":"Cuisson","min":8}},{"text":"Mixe le basilic, l'ail et l'huile, et ajoute ce pistou au moment de servir.","timer":null}],"variant":"Plus de légumes verts","change":"Avec des petits pois, des fèves et des épinards."}]$r$::jsonb, 'claude')
