insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('rapide', 'recettes rapides', array['expres', 'plat rapide', 'vite fait']::text[], 'list', $r$[{"title":"Œufs brouillés crémeux","intro":"Des œufs brouillés doucement, crémeux et fondants.","minutes":10,"calories":240,"difficulty":"Facile","imageSearch":"creamy scrambled eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":8,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":2,"unit":"c. à s.","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Bats légèrement les œufs.","timer":null},{"text":"Fais-les cuire à feu doux avec le beurre en remuant sans arrêt 4 min.","timer":{"label":"Poêle","min":4}},{"text":"Retire du feu quand ils sont encore un peu coulants et ajoute la crème, sel, poivre et ciboulette.","timer":null}],"kids":true},{"title":"Spaghetti carbonara","intro":"La vraie carbonara : des œufs, du pecorino et du guanciale, sans crème.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"pecorino râpé","plural":"pecorino râpé","qty":60,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti dans l'eau bouillante