on.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"couscous tabbouleh salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":250,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Verse 25 cl d'eau bouillante salée sur la semoule, couvre 5 min et égrène à la fourchette.","timer":{"label":"Repos","min":5}},{"text":"Coupe les tomates, le concombre et l'oignon en petits dés.","timer":null},{"text":"Mélange avec la semoule, la menthe et le persil ciselés, le jus des citrons, l'huile, sel et poivre.","timer":null},{"text":"Mets au frais 1 h.","timer":{"label":"Frais","min":60}}],"kids":true},{"title":"Piperade","intro":"Les poivrons et tomates fondus du Pays basque, avec du jambon de Bayonne.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"piperade basque","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"poivron vert","plural":"poivrons verts","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"jambon de Bayonne","plural":"jambon de Bayonne","qty":4,"unit":"tranches","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Émince les oignons et les poivrons, et coupe les tomates en dés.","timer":null},{"text":"Fais fondre les oignons et les poivrons 15 min dans l'huile.","timer":{"label":"Poêle","min":15}},{"text":"Ajoute les tomates, l'ail et le piment d'Espelette, et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Fais griller le jambon quelques secondes à la poêle et pose-le sur la piperade.","timer":null}]},{"title":"Poke bowl au saumon","intro":"Du riz vinaigré, du saumon cru mariné au soja, de l'avocat, du concombre et du sésame.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"salmon poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"Plat hawaïen","serves":4,"items":[{"name":"riz à sushi","plural":"riz à sushi","qty":250,"unit":"g","have":false},{"name":"pavé de saumon extra-frais","plural":"pavés de saumon extra-frais","qty":2,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais cuire le riz, puis mélange-le avec le vinaigre de riz et laisse tiédir.","timer":{"label":"Cuisson","min":15}},{"text":"Coupe le saumon en cubes et fais-le mariner 10 min dans la sauce soja.","timer":{"label":"Marinade","min":10}},{"text":"Coupe l'avocat et le concombre.","timer":null},{"text":"Dans des bols, mets le riz, le saumon, les légumes, les edamame, le sésame et l'oignon.","timer":null}]},{"title":"Tzatziki","intro":"Le yaourt grec au concombre, à l'ail et à l'aneth, pour l'apéritif ou les grillades.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"tzatziki","veg":true,"oven":false,"cold":true,"missing":"","origin":"Recette grecque","serves":4,"items":[{"name":"yaourt grec","plural":"yaourts grecs","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Râpe le concombre, sale-le et laisse-le dégorger 10 min.","timer":null},{"text":"Presse-le bien dans tes mains pour retirer l'eau.","timer":null},{"text":"Mélange-le avec le yaourt, l'ail écrasé, l'aneth et le jus du citron.","timer":null},{"text":"Arrose d'un filet d'huile d'olive et garde au frais.","timer":null}]},{"title":"Pommes de terre sautées","intro":"Des pommes de terre dorées à la poêle, avec de l'ail et du persil.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"pan fried potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les pommes de terre et coupe-les en dés.","timer":null},{"text":"Fais-les dorer 25 min dans l'huile et le beurre à feu moyen, en remuant souvent.","timer":{"label":"Poêle","min":25}},{"text":"Ajoute l'ail et le persil hachés en fin de cuisson.","timer":null},{"text":"Sale et poivre.","timer":null}],"kids":true},{"title":"Chia pudding","intro":"Des graines de chia gonflées dans du lait de coco, avec des fruits frais.","minutes":10,"calories":250,"difficulty":"Facile","imageSearch":"chia pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"graines de chia","plural":"graines de chia","qty":80,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"sirop d'érable","plural":"sirop d'érable","qty":2,"unit":"c. à s.","have":false},{"name":"mangue","plural":"mangues","qty":1,"unit":"","have":false}],"steps":[{"text":"Mélange les graines de chia, le lait de coco et le sirop d'érable.","timer":null},{"text":"Remue de nouveau après 10 min pour éviter les grumeaux.","timer":null},{"text":"Laisse prendre au moins 4 h au frais.","timer":null},{"text":"Sers avec la mangue en dés.","timer":null}],"dessert":true},{"title":"Salade de quinoa","intro":"Du quinoa avec concombre, tomates, feta et herbes, comme un taboulé.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"feta","plural":"fetas","qty":150,"unit":"g","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":