r":null}]},{"title":"Gyozas au porc","intro":"Les raviolis japonais grillés dessous et cuits à la vapeur dessus, farcis au porc et au chou.","minutes":60,"calories":320,"difficulty":"Difficile","imageSearch":"pork gyoza dumplings","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette japonaise","serves":4,"items":[{"name":"feuilles à gyoza","plural":"feuilles à gyoza","qty":30,"unit":"","have":false},{"name":"porc haché","plural":"porc haché","qty":300,"unit":"g","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"huile de sésame","plural":"huile de sésame","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Hache finement le chou, sale-le et presse-le pour retirer l'eau.","timer":null},{"text":"Mélange-le avec le porc, l'ail, le gingembre, 1 c. à s. de sauce soja et l'huile de sésame.","timer":null},{"text":"Mets une cuillerée de farce sur chaque feuille, mouille le bord et plisse pour fermer.","timer":null},{"text":"Fais dorer les gyozas 3 min dans une poêle huilée.","timer":{"label":"Poêle","min":3}},{"text":"Verse 10 cl d'eau, couvre et laisse 5 min.","timer":{"label":"Vapeur","min":5}},{"text":"Sers avec le reste de sauce soja.","timer":null}]},{"title":"Bruschetta tomate basilic","intro":"Du pain grillé frotté à l'ail, garni de tomates fraîches au basilic.","minutes":15,"calories":220,"difficulty":"Facile","imageSearch":"tomato bruschetta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"pain de campagne","plural":"pains de campagne","qty":8,"unit":"tranches","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les tomates en petits dés et mélange-les avec le basilic, 3 c. à s. d'huile, sel et poivre.","timer":null},{"text":"Fais griller le pain et frotte-le avec l'ail.","timer":null},{"text":"Garnis de tomates et arrose d'un filet d'huile.","timer":null}]},{"title":"Tartare de saumon","intro":"Du saumon cru coupé au couteau, avec citron vert, échalote et herbes.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"salmon tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pavé de saumon extra-frais","plural":"pavés de saumon extra-frais","qty":3,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le saumon en petits dés bien réguliers.","timer":null},{"text":"Mélange avec l'échalote hachée, la ciboulette, l'huile, le jus des citrons, sel et poivre.","timer":null},{"text":"Mets au frais 10 min avant de servir.","timer":{"label":"Frais","min":10}}]},{"title":"Soupe à l'oignon gratinée","intro":"Des oignons longuement caramélisés dans un bouillon, sous un croûton gratiné au fromage.","minutes":70,"calories":420,"difficulty":"Facile","imageSearch":"french onion soup","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"oignon","plural":"oignons","qty":6,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":0.5,"unit":"","have":false},{"name":"gruyère râpé","plural":"gruyère râpé","qty":100,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Émince finement les oignons et fais-les fondre dans le beurre 30 min à feu doux, jusqu'à ce qu'ils soient bien dorés.","timer":{"label":"Cuisson","min":30}},{"text":"Saupoudre de farine, mélange, puis verse le vin blanc et 1,2 l d'eau avec le bouillon.","timer":null},{"text":"Laisse mijoter 20 min, sale et poivre.","timer":{"label":"Mijotage","min":20}},{"text":"Verse dans des bols, pose des tranches de pain grillé et couvre de gruyère.","timer":null},{"text":"Passe 5 min sous le gril du four.","timer":{"label":"Gril","min":5}}]},{"title":"Rouleaux de printemps aux crevettes","intro":"Des galettes de riz roulées avec crevettes, vermicelles, salade et menthe, sans cuisson.","minutes":30,"calories":220,"difficulty":"Moyen","imageSearch":"fresh spring rolls shrimp","veg":false,"oven":false,"cold":true,"missing":"","origin":"Recette vietnamienne","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":8,"unit":"","have":false},{"name":"crevette cuite","plural":"crevettes cuites","qty":16,"unit":"","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":80,"unit":"g","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"sauce hoisin","plural":"sauce hoisin","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais tremper les vermicelles 5 min dans l'eau chaude et égoutte-les.","timer":null},{"text":"Râpe la carotte et décortique les crevettes.","timer":null},{"text":"Trempe une galette quelques secondes dans l'eau tiède et pose-la à plat.","timer":null},{"text":"Garnis de salade, vermicelles, carotte et menthe, puis de 2 crevettes coupées en deux.","timer":null},{"text":"Replie les côtés et roule serré. Sers avec la sauce hoisin.","timer":null}]},{"title":"Taboulé","intro":"La semoule fraîche à la tomate, au concombre, à la menthe et au citron.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"couscous tabbouleh salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":250,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Verse 25 cl d'eau bouillante salée sur la semoule, couvre 5 min et égrène à la fourchette.","timer":{"label":"Repos","min":5}},{"text":"Coupe les tomates, le concombre et l'oignon en petits dés.","timer":null},{"text":"Mélange avec la semoule, la menthe et le persil ciselés, le jus des citrons, l'huile, sel et poivre.","timer":null},{"text":"Mets au frais 1 h.","timer":{"label":"Frai